import {creditedPNG} from './png-export.js';
import {materials,crafts,layouts,defaultProject,sanitizeProject,compatible,clamp,dimensions} from './workshop-model.js';
import {WorkshopRenderer} from './workshop-renderer.js';
import {esc} from './study-data.js';
const $=id=>document.getElementById(id),storageKey='jingchu-workshop-v1',favoriteKey='jingchu-rubbing-favorites',history=[],future=[];
let entries=[],project=defaultProject(),selected=project.layers[0].id,renderer,revision=0,pageSize=24,favorites=new Set(),savedOnly=false,objectFilter=new URLSearchParams(location.search).get('object'),pendingCraft=null;
const entry=id=>entries.find(e=>e.id===id),layer=()=>project.layers.find(l=>l.id===selected),uid=()=>crypto.randomUUID();
function toast(message){$('atelier-toast').textContent=message;$('atelier-toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('atelier-toast').hidden=true,3500)}
function remember(){history.push(JSON.stringify(project));if(history.length>35)history.shift();future.length=0}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(project));$('save-status').textContent='已保存到此浏览器'}catch{$('save-status').textContent='浏览器存储不可用，请保存设计文件'}}
function change(update){remember();update();if(!compatible(project.material,project.craft)){project.craft=null;toast('底材已更换，原工艺效果已移除。')}persist();syncControls();paint()}
function setTab(name){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===name)));$('studio').hidden=name!=='studio';$('library').hidden=name!=='library';if(name==='library')renderLibrary();else paint()}
async function paint(){
 const seq=++revision,snapshot=structuredClone(project),a=document.createElement('canvas'),b=document.createElement('canvas');
 try{await Promise.all([renderer.draw(a,snapshot),renderer.draw(b,snapshot,{unit:true,guides:true,selected})]);if(seq!==revision)return;for(const [id,source] of [['design-canvas',a],['unit-canvas',b]]){const target=$(id);target.width=source.width;target.height=source.height;target.getContext('2d').drawImage(source,0,0)}$('design-canvas').dataset.format=project.format;$('design-canvas').dataset.layers=String(project.layers.length);$('design-canvas').dataset.craft=project.craft||'none'}catch(error){toast(error.message)}
}
function syncControls(){
 const material=materials.find(m=>m.id===project.material),color=material.colors.find(([,v])=>v===project.background);
 $('materials').innerHTML=materials.map(m=>`<button data-material="${m.id}" aria-pressed="${m.id===project.material}" title="${m.subtitle}"><i style="--sample:${m.colors[0][1]}"></i>${m.name}</button>`).join('');
 $('backgrounds').innerHTML=material.colors.map(([name,value])=>`<button data-background="${value}" aria-label="${name}底色" aria-pressed="${value===project.background}" style="--swatch:${value}" title="${name}"></button>`).join('');$('background-name').textContent=color?.[0]||'自选';$('background-color').value=project.background;
 $('layouts').innerHTML=layouts.map(([id,name])=>`<button data-layout="${id}" aria-pressed="${id===project.layout}">${name}</button>`).join('');$('format').value=project.format;for(const key of ['size','gapX','gapY']){$(key).value=project[key];$(key+'-output').textContent=project[key]}
 $('crafts').innerHTML=crafts.map(c=>`<button data-craft="${c.id}" aria-pressed="${c.id===project.craft}" class="${compatible(project.material,c.id)?'':'incompatible'}" title="了解${c.name}${compatible(project.material,c.id)?'':'（需更换底材）'}"><i>${c.icon}</i>${c.name}</button>`).join('');$('craft-state').textContent=project.craft?crafts.find(c=>c.id===project.craft).effect:'点选工艺，先了解制作方法。';$('remove-craft').hidden=!project.craft;
 $('design-caption').textContent=(color?.[0]||'自选色')+' · '+material.name+ (project.craft?' / '+crafts.find(c=>c.id===project.craft).name:'');$('design-layout').textContent=layouts.find(([id])=>id===project.layout)[1];$('undo').disabled=!history.length;$('redo').disabled=!future.length;
 if(!layer())selected=project.layers.at(-1)?.id;renderLayers();
}
function renderLayers(){
 $('layers').innerHTML=project.layers.map((l,i)=>{const e=entry(l.rubbing);return `<div class="layer-row ${l.id===selected?'selected':''}"><button data-select-layer="${l.id}" aria-pressed="${l.id===selected}"><img src="${esc(e.image)}" alt=""><span>${esc(e.motif)}<small>${i+1} · ${esc(e.kind)}</small></span></button><button data-remove-layer="${l.id}" aria-label="删除第${i+1}个纹样图层">×</button></div>`}).join('')||'<p class="control-note">点「添加」，选择第一张纹样。</p>';
 const l=layer();$('layer-properties').innerHTML=l?`<div class="layer-tools"><button data-layer-action="duplicate">复制</button><button data-layer-action="back">下移</button><button data-layer-action="front">上移</button><button data-inspect="${l.rubbing}">看原器 ↗</button></div><label>纹样颜色</label><div class="layer-color-row"><input type="color" aria-label="所选纹样颜色" id="layer-color" value="${l.color}"><button data-layer-action="flip" aria-pressed="${l.flip}">水平镜像 ↔</button></div>${[['weight','线条粗细',1,3,.1,(l.weight||1.5).toFixed(1)],['size','局部大小',.15,1.6,.01,l.size.toFixed(2)],['rotation','旋转角度',-180,180,5,l.rotation+'°'],['opacity','透明度',.1,1,.05,Math.round(l.opacity*100)+'%'],['x','水平位置',-.7,.7,.02,l.x.toFixed(2)],['y','垂直位置',-.7,.7,.02,l.y.toFixed(2)]].map(([key,name,min,max,step,value])=>`<label>${name} <output id="layer-${key}-output">${value}</output><input type="range" data-layer-field="${key}" aria-label="${name}" min="${min}" max="${max}" step="${step}" value="${l[key]}"></label>`).join('')}`:'';
}
function addRubbing(id){const e=entry(id);if(!e?.available)return;if(project.layers.length>=8){toast('每组最多叠放 8 层，可先删除一层。');return}change(()=>{const l={id:uid(),rubbing:id,x:0,y:0,size:.85,rotation:0,flip:false,color:'#d1bf87',opacity:1,weight:1.5};project.layers.push(l);selected=l.id});setTab('studio');toast('已加入纹样组，可拖动调整位置。')}
function renderLibrary(){
 const search=$('pattern-search').value.trim().toLowerCase(),motif=$('motif-filter').value,kind=$('kind-filter').value;
 const list=entries.filter(e=>(!objectFilter||e.objectId===objectFilter)&&(!search||[e.title,e.motif,e.era].join(' ').toLowerCase().includes(search))&&(!motif||e.motif===motif)&&(!kind||e.view===kind)&&(!savedOnly||favorites.has(e.id)));
 const featured=['hb-4781-1','jz-351-2','hb-5063-1','jz-458-3','jz-469-2','hb-4980-1','drum-3'];const score=e=>featured.includes(e.id)?featured.indexOf(e.id)-100:e.view==='detail'?0:e.view==='form'?1:e.view==='context'?2:3;list.sort((a,b)=>score(a)-score(b));
 $('result-count').textContent=list.length+' 条';$('library-description').textContent=objectFilter?(entries.find(e=>e.objectId===objectFilter)?.title||'当前器物')+'的纹样记录。点「清除筛选」浏览全部。':'从馆藏照片逐件提取；区分纹样、器表与造型，未补绘不可见部分。';
 $('pattern-grid').innerHTML=list.slice(0,pageSize).map(e=>`<article class="pattern-card"><button class="rubbing-preview" data-inspect="${e.id}" aria-label="查看${esc(e.title)}的${esc(e.motif)}拓影与原图"><span class="pattern-kind">${e.kind}</span>${e.available?`<img src="${e.image}" alt="${esc(e.label)}数字拓影" loading="lazy">`:'<span class="unavailable">原照片未能辨清<br>保留出处，未作补绘</span>'}</button><h3>${esc(e.motif)} <span>· ${esc(e.label)}</span></h3><p>${esc(e.title)}</p><p>${esc(e.era)}</p><div class="pattern-buttons"><button data-favorite="${e.id}" aria-label="${favorites.has(e.id)?'取消收藏':'收藏'}${esc(e.title)}${esc(e.motif)}" aria-pressed="${favorites.has(e.id)}">${favorites.has(e.id)?'♥':'♡'}</button>${e.available?`<button data-download="${e.id}" title="保存透明 PNG">↓ PNG</button><button class="add-rubbing" data-add="${e.id}">＋ 叠入</button>`:`<a href="object.html?id=${e.objectId}">器物档案 ↗</a>`}</div></article>`).join('')||'<p class="control-note">暂无匹配纹样，试试减少筛选条件。</p>';$('more-patterns').hidden=list.length<=pageSize;
}
function creditHTML(e){return e.credit?`<p>摄影：${esc(e.credit.author)} · <a href="${esc(e.credit.page)}" target="_blank" rel="noopener">${esc(e.credit.provider)}</a>${e.credit.licenseURL?` · <a href="${esc(e.credit.licenseURL)}" target="_blank" rel="noopener">${esc(e.credit.license)}</a>`:''}<br>已作局部裁切、去背景与单色拓影处理。</p>`:'<p>图像来自馆方公开藏品档案；已作局部裁切与单色拓影处理。</p>'}
function inspectPattern(id){
 const e=entry(id);if(!e)return;const dialog=$('pattern-dialog');dialog.innerHTML=`<button class="dialog-close" data-close="pattern-dialog" aria-label="关闭纹样详情">×</button><p class="eyebrow">PHOTO TO IMPRESSION</p><h2 id="pattern-title">${esc(e.motif)} · ${esc(e.kind)}</h2><div class="pattern-comparison"><div><small>原器物照片</small><img src="${esc(e.photo)}" alt="${esc(e.title)}"></div><div><small>${e.available?'局部数字拓影':'暂不生成'}</small>${e.available?`<img src="${e.image}" alt="${esc(e.label)}">`:'<p>当前照片无法辨清这处纹样。</p>'}</div></div><p>${esc(e.title)}<br>${esc(e.label)} · ${esc(e.note)}</p><p>照片提纹，非实物拓片。${e.view==='context'?'本条包含器表整体，不能当作已独立辨清的纹样母题。':''}</p>${creditHTML(e)}<a href="${esc(e.source)}" target="_blank" rel="noopener">馆方记录 ↗</a>　<a href="object.html?id=${e.objectId}">打开器物档案 ↗</a>${e.available?`<div class="pattern-detail-actions"><button class="gold-button" data-add="${e.id}">加入我的设计</button><button class="quiet-button" data-download="${e.id}">保存透明拓影 PNG</button></div>`:''}`;dialog.showModal();
}
function craftDialog(id){
 const c=crafts.find(c=>c.id===id);if(!c)return;pendingCraft=id;const valid=compatible(project.material,id);$('craft-dialog').innerHTML=`<button class="dialog-close" data-close="craft-dialog" aria-label="关闭工艺说明">×</button><p class="eyebrow">CRAFT NOTES / 看懂，再动手</p><h2 id="craft-title">${c.name}</h2><div class="craft-explanation"><figure><img src="${c.image}" alt="${esc(c.caption)}"><figcaption>${esc(c.caption)}<br><a href="${c.imageSource}" target="_blank" rel="noopener">图片与藏品出处 ↗</a></figcaption></figure><div><p>${c.summary}</p><ol>${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol><a href="${c.source}" target="_blank" rel="noopener">${c.sourceTitle} ↗</a><p class="effect-note">画面效果：${c.effect}<br>工艺示例用于理解制作方法，不表示所选拓影原器物采用此工艺。</p></div></div><div class="craft-apply"><p>${valid?'适用当前底材 · '+materials.find(m=>m.id===project.material).name:c.incompatible}</p><button class="gold-button" id="apply-craft" ${valid?'':'disabled'}>${valid?'了解了，应用此工艺':'先更换底材'}</button></div>`;$('craft-dialog').showModal();
}
function showSources(){const list=[...new Set(project.layers.map(l=>l.rubbing))].map(entry);$('sources-dialog').innerHTML='<button class="dialog-close" data-close="sources-dialog" aria-label="关闭纹样来源">×</button><p class="eyebrow">EVERY LINE HAS A SOURCE</p><h2 id="sources-title">这张作品的纹样来处</h2>'+list.map(e=>`<div class="source-entry"><strong>${esc(e.title)} · ${esc(e.motif)}</strong><br>${esc(e.kind)} / ${esc(e.label)}<a href="${esc(e.source)}" target="_blank" rel="noopener">${esc(e.source)}</a>${creditHTML(e)}</div>`).join('')+'<p class="control-note">保存的设计文件和导出 PNG 的文字元数据均附带来源。带有 CC BY-SA 标识的照片衍生部分继续按相同许可分享；其他图像保留原来源权利。</p>';$('sources-dialog').showModal()}
const attribution=()=>[...new Set(project.layers.map(l=>l.rubbing))].map(entry).map(e=>({rubbing:e.id,title:e.title,motif:e.motif,source:e.source,credit:e.credit,changes:'局部裁切、照片数字拓影、重新配色与排布'}));
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function downloadRubbing(id){try{const e=entry(id);if(!e?.available)return;const response=await fetch(e.image);if(!response.ok)throw new Error('图片未能读取');const blob=await creditedPNG(await response.blob(),{...e,changes:'馆藏照片局部裁切与单色拓影'});download(blob,'荆楚拓影-'+e.title+'-'+e.motif+'.png');toast('已保存透明拓影，文件附带来源信息。')}catch(error){toast('保存失败：'+error.message)}}
async function exportImage(){const button=$('export-image');button.disabled=true;button.textContent='正在生成…';try{const c=document.createElement('canvas');await renderer.draw(c,structuredClone(project));const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));const credited=await creditedPNG(blob,{title:'荆楚纹样工坊作品',sources:attribution(),design:project}),name='荆楚纹样-'+materials.find(m=>m.id===project.material).name+'.png';download(credited,name);let link=$('download-ready');if(!link){link=document.createElement('a');link.id='download-ready';link.className='download-ready';document.querySelector('.atelier-actions').append(link)}if(link.dataset.url)URL.revokeObjectURL(link.dataset.url);link.href=URL.createObjectURL(credited);link.dataset.url=link.href;link.download=name;link.textContent='再次下载 PNG ↓';toast('作品已导出，PNG 内含纹样来源信息。')}catch(error){toast('导出失败：'+error.message)}finally{button.disabled=false;button.textContent='导出作品 PNG ↗'}}
function preset(name){change(()=>{project.layers=[];project.layout=name==='cloud'?'grid':'stagger';project.size=name==='floral'?225:210;project.gapX=15;project.gapY=15;const make=(rubbing,x,y,rotation=0,flip=false,size=.85,color='#d1bf87')=>({id:uid(),rubbing,x,y,rotation,flip,size,color,opacity:1,weight:1.5});if(name==='paired')project.layers=[make('hb-4781-1',-.21,0,0,false,.72),make('hb-4781-1',.21,0,0,true,.72)];if(name==='floral')project.layers=[0,1,2,3].map(i=>make('jz-351-2',Math.cos(i*Math.PI/2)*.18,Math.sin(i*Math.PI/2)*.18,i*90,false,.66,i%2?'#b4c49b':'#dbc89a'));if(name==='cloud')project.layers=[make('hb-6174-1',0,0,0,false,1.15)];selected=project.layers[0]?.id});toast('排布已更新，可撤销返回。')}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab)setTab(b.dataset.tab);
 if(b.dataset.material)change(()=>{project.material=b.dataset.material;project.background=materials.find(m=>m.id===project.material).colors[0][1]});
 if(b.dataset.background)change(()=>project.background=b.dataset.background);
 if(b.dataset.layout)change(()=>project.layout=b.dataset.layout);
 if(b.dataset.craft)craftDialog(b.dataset.craft);
 if(b.id==='apply-craft'&&compatible(project.material,pendingCraft)){change(()=>project.craft=pendingCraft);$('craft-dialog').close()}
 if(b.dataset.close)$(b.dataset.close).close();
 if(b.dataset.preset)preset(b.dataset.preset);
 if(b.dataset.selectLayer){selected=b.dataset.selectLayer;renderLayers();paint()}
 if(b.dataset.removeLayer)change(()=>project.layers=project.layers.filter(l=>l.id!==b.dataset.removeLayer));
 if(b.dataset.layerAction){const l=layer();if(!l)return;const action=b.dataset.layerAction;if(action==='duplicate'&&project.layers.length>=8){toast('每组最多叠放 8 层。');return}change(()=>{const i=project.layers.indexOf(l);if(action==='flip')l.flip=!l.flip;if(action==='duplicate'){const copy={...l,id:uid(),x:clamp(l.x+.1,-.7,.7)};project.layers.push(copy);selected=copy.id}if(action==='front'&&i<project.layers.length-1)[project.layers[i],project.layers[i+1]]=[project.layers[i+1],project.layers[i]];if(action==='back'&&i>0)[project.layers[i],project.layers[i-1]]=[project.layers[i-1],project.layers[i]]})}
 if(b.dataset.add){$('pattern-dialog').close();addRubbing(b.dataset.add)}
 if(b.dataset.inspect)inspectPattern(b.dataset.inspect);
 if(b.dataset.download)downloadRubbing(b.dataset.download);
 if(b.dataset.favorite){const id=b.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem(favoriteKey,JSON.stringify([...favorites]))}catch{toast('当前浏览器无法保存收藏。')}renderLibrary()}
});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('add-pattern').onclick=()=>{objectFilter=null;setTab('library')};$('remove-craft').onclick=()=>change(()=>project.craft=null);$('view-sources').onclick=showSources;
$('background-color').onchange=e=>change(()=>project.background=e.target.value);$('format').onchange=e=>change(()=>project.format=e.target.value);
for(const key of ['size','gapX','gapY']){$(key).onpointerdown=()=>remember();$(key).onkeydown=e=>{if(e.key.startsWith('Arrow'))remember()};$(key).oninput=e=>{project[key]=Number(e.target.value);$(key+'-output').textContent=project[key];paint()};$(key).onchange=()=>{persist();$('undo').disabled=!history.length}}
$('layer-properties').addEventListener('change',e=>{if(e.target.id==='layer-color')change(()=>layer().color=e.target.value);if(e.target.dataset.layerField){persist();$('undo').disabled=!history.length}});
$('layer-properties').addEventListener('pointerdown',e=>{if(e.target.dataset.layerField)remember()});$('layer-properties').addEventListener('keydown',e=>{if(e.target.dataset.layerField&&e.key.startsWith('Arrow'))remember()});
$('layer-properties').addEventListener('input',e=>{const key=e.target.dataset.layerField;if(key&&layer()){layer()[key]=Number(e.target.value);$('layer-'+key+'-output').textContent=key==='rotation'?layer()[key]+'°':key==='opacity'?Math.round(layer()[key]*100)+'%':layer()[key].toFixed(2);paint()}});
let drag=null;const unit=$('unit-canvas');unit.onpointerdown=e=>{if(!layer())return;remember();unit.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:layer().x,startY:layer().y,id:selected};unit.focus()};unit.onpointermove=e=>{if(!drag)return;const l=project.layers.find(l=>l.id===drag.id),scale=unit.getBoundingClientRect().width*400/600;l.x=clamp(drag.startX+(e.clientX-drag.x)/scale,-.7,.7);l.y=clamp(drag.startY+(e.clientY-drag.y)/scale,-.7,.7);paint()};unit.onpointerup=()=>{if(drag){drag=null;persist();renderLayers();$('undo').disabled=false}};unit.onpointercancel=unit.onpointerup;unit.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||!layer())return;e.preventDefault();change(()=>{const key=e.key==='ArrowLeft'||e.key==='ArrowRight'?'x':'y',delta=e.key==='ArrowLeft'||e.key==='ArrowUp'?-.02:.02;layer()[key]=clamp(layer()[key]+delta,-.7,.7)})};
$('undo').onclick=()=>{if(!history.length)return;future.push(JSON.stringify(project));project=JSON.parse(history.pop());persist();syncControls();paint()};$('redo').onclick=()=>{if(!future.length)return;history.push(JSON.stringify(project));project=JSON.parse(future.pop());persist();syncControls();paint()};
for(const id of ['pattern-search','motif-filter','kind-filter'])$(id).addEventListener(id==='pattern-search'?'input':'change',()=>{pageSize=24;renderLibrary()});$('saved-only').onclick=()=>{savedOnly=!savedOnly;$('saved-only').setAttribute('aria-pressed',String(savedOnly));pageSize=24;renderLibrary()};$('more-patterns').onclick=()=>{pageSize+=24;renderLibrary()};$('clear-library').onclick=()=>{objectFilter=null;for(const id of ['pattern-search','motif-filter','kind-filter'])$(id).value='';savedOnly=false;$('saved-only').setAttribute('aria-pressed','false');pageSize=24;renderLibrary()};
$('export-image').onclick=exportImage;$('export-project').onclick=()=>{download(new Blob([JSON.stringify({...project,sources:attribution()},null,2)],{type:'application/json'}),'荆楚纹样设计.json');toast('设计文件已保存，之后可通过「打开设计」继续编辑。')};$('import-project').onclick=()=>$('project-file').click();$('project-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw new Error('设计文件过大。');const next=sanitizeProject(JSON.parse(await file.text()),entries);change(()=>project=next);setTab('studio');toast('设计已打开。')}catch(error){toast('无法打开：'+error.message)}finally{e.target.value=''}};
try{const r=await fetch('data/rubbings.json');if(!r.ok)throw new Error('纹样资料读取失败');entries=(await r.json()).entries;try{const saved=localStorage.getItem(storageKey);if(saved)project=sanitizeProject(JSON.parse(saved),entries);favorites=new Set(JSON.parse(localStorage.getItem(favoriteKey)||'[]'))}catch{}renderer=new WorkshopRenderer(entries);$('library-count').textContent=entries.filter(e=>e.available).length+' 张';$('motif-filter').innerHTML='<option value="">全部纹样</option>'+[...new Set(entries.map(e=>e.motif))].map(m=>`<option>${esc(m)}</option>`).join('');syncControls();await paint();if(objectFilter)setTab('library');document.body.dataset.ready='true'}catch(error){$('save-status').textContent=error.message;toast(error.message)}
